import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksFor,validEndo,advanceEndo,numericEndo}from './endo-models.js?v=20261023-physicscomplete01';import{showEndo}from './endo-visuals.js?v=20261023-physicscomplete01';export{showEndo};
export function mountEndo(l,p,root,{save,done,feedback}){let ts=tasksFor(l.widget.slice(5),l.learnerTier),w=p.widget;w.endoTask??=ts[0].id;w.endoDrafts??={};w.endoPassed??=[];let i=ts.findIndex(t=>t.id===w.endoTask);if(i<0)i=0;let t=ts[i],v=w.endoDrafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEndo(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.endoPassed.includes(t.id));
syncProcessMovie(l,1,['glands','data','risk','diabetes'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('endoCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('endoAnswer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEndo">Reveal evidence →</button><p id="endoReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEndo(t.kind,{state:c[0],neutral:t.kind==='glands',title:t.title,label:c[1],concealed:!r&&t.kind!=='glands',progress:r?1:0,step:r?5:0});$('#endoReadout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEndo(c,v.answer);}
else if(t.type==='sequence'){body=field('endoNext','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEndo">Advance pathway →</button><p id="endoReadout" aria-live="polite"></p>';draw=()=>{showEndo(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#endoReadout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="endoNumber">Your result / mmol/L</label><input class="lab-input" id="endoNumber" type="number" step="any" value="'+(v.number??'')+'">'+field('endoReason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEndo('data',{title:t.title,label:'Original supplied curves · not clinical data'});valid=()=>numericEndo(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="endoEvidence"></p><div class="lab-actions"><button class="secondary" id="recordEndo">Record reasoning</button><button class="secondary" id="nextEndo">Next challenge →</button></div><p id="endoProgress"></p>';
const status=()=>{$('#endoEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.endoPassed.includes(t.id)?'Challenge recorded.':'';$('#endoProgress').textContent=ts.filter(t=>w.endoPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='endoCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='endoAnswer')v.answer=val;else if(id==='endoNext')v.next=val;else if(id==='endoNumber')v.number=val;else if(id==='endoReason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v.number=e.target.value;save();};}
if($('#revealEndo'))$('#revealEndo').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEndo(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEndo(t.cases[v.case],v.answer));};
if($('#advanceEndo'))$('#advanceEndo').onclick=()=>{let n=advanceEndo(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEndo').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.endoPassed.includes(t.id))w.endoPassed.push(t.id);p.widgetDone=ts.every(t=>w.endoPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextEndo').onclick=()=>{if(!w.endoPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.endoTask=ts[(i+1)%ts.length].id;save();remount();};}
